import skip from "@/lib/legacy-image-skip.json";

/**
 * Responsive WebP variants of legacy assets, pre-generated by
 * migration/scrape/optimize-images.mjs:  /legacy/<p>  ->  /legacy-opt/<p>.w{480,960,1600}.webp
 * (served from Supabase Storage in production via the rewrite in next.config.mjs).
 */
export const LEGACY_WIDTHS = [480, 960, 1600] as const;
const RASTER = /\.(jpe?g|png|webp)$/i;
const undecodable = new Set<string>(skip);

function legacyPath(src: string): string | null {
  if (!src.startsWith("/legacy/")) return null;
  const rel = src.slice("/legacy/".length);
  let decoded = rel;
  try {
    decoded = decodeURIComponent(rel);
  } catch {}
  if (!RASTER.test(decoded) || undecodable.has(decoded)) return null;
  return rel;
}

export const legacyVariant = (src: string, width: (typeof LEGACY_WIDTHS)[number]) => {
  const rel = legacyPath(src);
  return rel ? `/legacy-opt/${rel}.w${width}.webp` : null;
};

/** srcset for an <img>; null when the source has no variants (non-legacy, SVG, GIF, …). */
export function legacySrcSet(src: string) {
  const rel = legacyPath(src);
  if (!rel) return null;
  return {
    src: `/legacy-opt/${rel}.w960.webp`,
    srcSet: LEGACY_WIDTHS.map((w) => `/legacy-opt/${rel}.w${w}.webp ${w}w`).join(", "),
  };
}

/** Optimised URL for CSS backgrounds (hero slides, banners). Falls back to the original. */
export const bgUrl = (src: string | null | undefined, width: (typeof LEGACY_WIDTHS)[number] = 1600) =>
  src ? (legacyVariant(src, width) ?? src) : src;
